-- Syncro: per-user data with row level security.
-- Ids are generated by the client and default items share ids across users
-- (e.g. workspace 'geral'), so every primary key is (user_id, id).
-- Rows are soft-deleted so deletions reach the other devices on their next pull.

create or replace function public.touch_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := clock_timestamp();
  return new;
end;
$$;

create table public.profiles (
  user_id uuid primary key default auth.uid() references auth.users (id) on delete cascade,
  name text not null default '' check (char_length(name) <= 60),
  photo text check (photo is null or char_length(photo) <= 200000),
  sleep jsonb not null default '{}'::jsonb,
  reset text not null default '',
  updated_at timestamptz not null default clock_timestamp()
);

create table public.workspaces (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  name text not null check (char_length(name) between 1 and 60),
  notes text not null default '' check (char_length(notes) <= 5000),
  position integer not null default 0,
  deleted boolean not null default false,
  updated_at timestamptz not null default clock_timestamp(),
  primary key (user_id, id)
);

create table public.tasks (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  title text not null check (char_length(title) between 1 and 120),
  due date,
  priority text not null default 'media' check (priority in ('urgente', 'alta', 'media', 'baixa')),
  done boolean not null default false,
  effort text check (effort is null or effort in ('rel', 'lig', 'cui', 'exi', 'pro')),
  workspace_id text not null default 'geral',
  notes text not null default '' check (char_length(notes) <= 2000),
  position integer not null default 0,
  deleted boolean not null default false,
  updated_at timestamptz not null default clock_timestamp(),
  primary key (user_id, id)
);

create table public.event_categories (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  name text not null check (char_length(name) between 1 and 60),
  color text not null check (color ~* '^#[0-9a-f]{6}$'),
  position integer not null default 0,
  deleted boolean not null default false,
  updated_at timestamptz not null default clock_timestamp(),
  primary key (user_id, id)
);

create table public.day_categories (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  name text not null check (char_length(name) between 1 and 60),
  color text not null check (color ~* '^#[0-9a-f]{6}$'),
  icon text check (icon is null or char_length(icon) <= 16),
  position integer not null default 0,
  deleted boolean not null default false,
  updated_at timestamptz not null default clock_timestamp(),
  primary key (user_id, id)
);

create table public.events (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  title text not null check (char_length(title) between 1 and 120),
  date date not null,
  start_time text not null check (start_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),
  end_time text not null check (end_time ~ '^([01][0-9]|2[0-4]):[0-5][0-9]$'),
  rep text not null default 'none' check (rep in ('none', 'daily', 'weekdays', 'custom', 'weekly')),
  days smallint[],
  category_id text not null default '',
  color text check (color is null or color ~* '^#[0-9a-f]{6}$'),
  done jsonb not null default '{}'::jsonb,
  exceptions jsonb,
  position integer not null default 0,
  deleted boolean not null default false,
  updated_at timestamptz not null default clock_timestamp(),
  primary key (user_id, id)
);

create table public.finances (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  type text not null check (type in ('in', 'out')),
  kind text not null check (kind in ('rec', 'one')),
  name text not null check (char_length(name) between 1 and 120),
  amount numeric(12, 2) not null check (amount > 0),
  date date not null,
  end_month text not null default '' check (end_month = '' or end_month ~ '^[0-9]{4}-[0-9]{2}$'),
  category_id text not null default '',
  position integer not null default 0,
  deleted boolean not null default false,
  updated_at timestamptz not null default clock_timestamp(),
  primary key (user_id, id)
);

create table public.special_days (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  name text not null check (char_length(name) between 1 and 120),
  category_id text not null default '',
  start_date date not null,
  end_date date,
  time text not null default '' check (time = '' or time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),
  notes text not null default '' check (char_length(notes) <= 400),
  yearly boolean not null default false,
  position integer not null default 0,
  deleted boolean not null default false,
  updated_at timestamptz not null default clock_timestamp(),
  primary key (user_id, id)
);

do $$
declare
  t text;
begin
  foreach t in array array['profiles', 'workspaces', 'tasks', 'event_categories', 'day_categories', 'events', 'finances', 'special_days']
  loop
    execute format('create trigger %I before insert or update on public.%I for each row execute function public.touch_updated_at()', t || '_touch', t);
    execute format('alter table public.%I enable row level security', t);
    execute format('create policy %I on public.%I for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id)', t || '_owner', t);
    execute format('create index %I on public.%I (user_id, updated_at)', t || '_changes', t);
  end loop;
end;
$$;
